// Книга АОВ1 с комплектом и протоколами плана 13: ПАВ (на комплект), ПКЛ (на акт), АИИ (на комплект, без перечня).
import { MemoryWorkbook } from "@idk/shared/workbook/memory";
import { isoToExcelSerial, type CellValue } from "@idk/shared/workbook/values";
import { aov1Records, AOV1 } from "./aov1Book.ts";

export { AOV1 };
const d = (iso: string) => isoToExcelSerial(iso);
type Recs = Record<string, Record<string, CellValue>[]>;

export function protoRecords(patch: (r: Recs) => void = () => {}): Recs {
  const r = aov1Records() as Recs;
  r["Комплекты"] = [{ "№ реестра": "1", "Шифр": "КУТ03-Р-ПИР-2-26-100-АОВ1.01.00", "Том": "1" }];
  r["АктыКомплектов"] = [{ "Комплект": "1", "Акт": AOV1 }];
  r["РеестрИД"] = [];
  r["Протоколы"] = [
    { "Документ": "ПАВ", "№ документа": "ПАВ-1", "Комплект": "1", "Дата / начало": d("2026-07-15"), "Предмет (что проверено)": "Щит ЩР-1" },
    { "Документ": "ПКЛ", "№ документа": "ПКЛ-1", "Акт": AOV1, "Дата / начало": d("2026-07-16") },
    { "Документ": "АИИ", "№ документа": "АИИ-1", "Комплект": "1", "Дата / начало": d("2026-07-20") },
  ];
  r["ЗамерыАвтоматов"] = [
    { "№ документа": "ПАВ-1", "Щит": "ЩР-1", "Обозначение по проекту": "QF1", "Тип аппарата": "ВА47-29 C16", "Iн, А": 16,
      "Время срабатывания по ТУ, с": "0,01–0,1", "Время срабатывания факт., с": 0.02 },
    { "№ документа": "ПАВ-1", "Щит": "ЩР-1", "Обозначение по проекту": "QF2", "Тип аппарата": "ВА47-29 C10", "Iн, А": 10,
      "Время срабатывания по ТУ, с": "0,01–0,1", "Время срабатывания факт., с": 0.03 },
  ];
  r["ИспытанияКЛ"] = [{ "№ документа": "ПКЛ-1", "Линия": "ВРУ-1 — ЩР-1", "Испытательное напряжение, кВ": 2.5, "Результат": "выдержала" }];
  r["ПереченьОборудования"] = [];
  for (const t of ["ЗамерыУЗО", "ЗамерыФазаНуль", "ЗамерыМеталлосвязи", "ЗамерыЗаземления", "ОсмотрБарабанов", "ПрогревБарабанов",
    "ТрубныеПроводки", "ЗамерыВолокон", "ЗамерыСКС"]) r[t] = [];
  patch(r);
  return r;
}

export const protoBook = (patch?: (r: Recs) => void) => new MemoryWorkbook(protoRecords(patch) as any);
